# Writes inputs/chars.l and cases-chars.txt: one entry per printable ASCII
# character X (codes 33-126) with "angle 4" and "axiom FXF+F", and one with
# "axiom FX2F+F" (a digit after X), to classify every character as a turtle
# command.  Entry names are cNNN and dNNN (NNN = decimal code).
#   python3 -I gen-chars.py
import os
here = os.path.dirname(os.path.abspath(__file__))
L, C = [], ['# SPDX-License-Identifier: GPL-3.0-or-later',
            '# Generated by gen-chars.py: every printable character inside an axiom.']
for code in range(33, 127):
    ch = chr(code)
    for pre, ax in (('c', f'F{ch}F+F'), ('d', f'F{ch}2F+F')):
        name = f'{pre}{code:03d}'
        L += [f'{name} {{', '  angle 4', f'  axiom {ax}', '}']
        C.append(f'{name} only=chars.l,uniq.map type=lsystem lfile=chars.l lname={name} params=0 viewwindows=2 map=uniq.map')
open(os.path.join(here, 'inputs', 'chars.l'), 'w').write('\n'.join(L) + '\n')
open(os.path.join(here, 'cases-chars.txt'), 'w').write('\n'.join(C) + '\n')
